import React from 'react';
import { TableColumnProps, TableProps } from '@arco-design/web-react';
import { ArrayField, FieldDisplayTypes, GeneralField } from '@formily/core';
import { RecursionField, Schema, useField, useFieldSchema } from '@formily/react';
import { isArr, isPlainObj } from '@formily/shared';
import ArrayBase from '../../ArrayBase';
import FormItemLabel from "../../FormItem/FormLabel";

export interface ObservableColumnSource {
  field?: GeneralField;
  columnProps: TableColumnProps<any>;
  schema: Schema;
  display: FieldDisplayTypes;
  name: string;
}

export const isColumnComponent = (schema: Schema) => schema['x-component']?.indexOf('Column') > -1;

const isOperationsComponent = (schema: Schema) => schema['x-component']?.indexOf('Operations') > -1;

const isAdditionComponent = (schema: Schema) => schema['x-component']?.indexOf('Addition') > -1;

export const useArrayTableSources = () => {
  const arrayField = useField();
  const schema = useFieldSchema();

  const parseSources = (schema: Schema): ObservableColumnSource[] => {
    if (isColumnComponent(schema) || isOperationsComponent(schema) || isAdditionComponent(schema)) {
      if (!schema['x-component-props']?.dataIndex && !schema.name) {
        return [];
      }
      const name = schema['x-component-props']?.dataIndex || schema.name;
      const field = arrayField.query(arrayField.address.concat(name)).take();
      const columnProps = field?.component?.[1] || schema['x-component-props'] || {};
      const display = field?.display || schema['x-display'] || 'visible';
      return [
        {
          name,
          display,
          field,
          schema,
          columnProps,
        },
      ];
    } else if (schema.properties) {
      return schema.reduceProperties((buf, schema) =>
        // @ts-ignore
        buf.concat(parseSources(schema))
        , []);
    }
    return [];
  };
  const parseArrayItems = (schema: Schema['items']) => {
    if (!schema) {
      return [];
    }
    const sources: ObservableColumnSource[] = [];
    const items = isArr(schema) ? schema : [schema];
    return items.reduce((columns, schema) => {
      const item = parseSources(schema);
      if (item) {
        return columns.concat(item);
      }
      return columns;
    }, sources);
  };

  if (!schema) {
    throw new Error('can not found schema object');
  }

  return parseArrayItems(schema.items);
};

export const useArrayTableColumns = (
  dataSource: any[],
  field: ArrayField,
  sources: ObservableColumnSource[]
): TableProps<any>['columns'] => sources.reduce((buf, { name, columnProps, schema, display }, key) => {
  if (display !== 'visible') {
    return buf;
  }
  if (!isColumnComponent(schema)) {
    return buf;
  }
  return buf?.concat({
    ...columnProps,
    key,
    dataIndex: name,
    render: (_: any, record: any) => {
      const index = dataSource?.indexOf(record);
      const children = (
        <ArrayBase.Item index={index} record={() => field?.value?.[index]}>
          <RecursionField schema={schema} name={index} onlyRenderProperties />
        </ArrayBase.Item>
      );
      return children;
    },
    title: isPlainObj(columnProps.title) ? <FormItemLabel showColon={false} requiredSymbol={true} {...columnProps.title}></FormItemLabel> : columnProps.title
  });
}, [] as TableProps<any>['columns']);

export const useAddition = () => {
  const schema = useFieldSchema();
  return schema.reduceProperties((addition, schema, key) => {
    if (isAdditionComponent(schema)) {
      return <RecursionField schema={schema} name={key} />;
    }
    return addition;
  }, null);
};
